import { NextResponse } from "next/server"

import { assertCourseAccess, clientForPrincipal, resolvePrincipal } from "@/lib/server/principal"

/**
 * Quizzes for one course.
 *
 * A teacher reads every quiz in the course including drafts, and controls
 * whether the class can see one. A student reads only published course quizzes
 * plus their own private practice quizzes.
 *
 * The teacher view previously reused the student component, which asked for
 * `student_id = <teacher id>` and so never matched a course-wide quiz. Quizzes
 * generated by a teacher were also saved unpublished, which meant a generated
 * quiz could never reach the class at all.
 */

type RouteContext = { params: Promise<{ courseId: string }> }

const QUIZ_COLUMNS =
  "id, course_id, material_id, title, questions, is_published, student_id, created_at"

export async function GET(_req: Request, { params }: RouteContext) {
  const { courseId } = await params
  const principal = await resolvePrincipal()
  if (!principal) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

  const course = await assertCourseAccess(principal, courseId)
  if (!course) return NextResponse.json({ error: "Course not found" }, { status: 404 })

  const supabase = await clientForPrincipal(principal)
  const isTeacher = principal.role === "teacher" || principal.role === "admin"

  let query = supabase.from("quizzes").select(QUIZ_COLUMNS).eq("course_id", course.id)

  if (!isTeacher) {
    if (!principal.isPersistable) {
      return NextResponse.json({ quizzes: [] })
    }
    // Course-wide published quizzes, plus this student's own practice quizzes.
    query = query.or(`student_id.is.null,student_id.eq.${principal.userId}`)
  }

  const { data, error } = await query.order("created_at", { ascending: false })
  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  const quizzes = (data ?? []).map((quiz: any) => ({
    ...quiz,
    // A student must never see the answer key before answering; the score is
    // computed server-side once they submit. Teachers need it to review.
    questions: isTeacher
      ? quiz.questions
      : (quiz.questions ?? []).map((question: any) => ({
          question: question.question,
          options: question.options,
        })),
  }))

  // Students only see published course quizzes; a draft is a teacher's work in
  // progress. RLS enforces this too, but demo sessions read through a
  // privileged client, so filter explicitly to keep behaviour identical.
  const visible = isTeacher
    ? quizzes
    : quizzes.filter((quiz: any) => quiz.student_id !== null || quiz.is_published)

  return NextResponse.json({ quizzes: visible })
}

/** PATCH — publish or unpublish a quiz. Teacher only. */
export async function PATCH(req: Request, { params }: RouteContext) {
  const { courseId } = await params
  const principal = await resolvePrincipal()
  if (!principal) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

  if (principal.role !== "teacher" && principal.role !== "admin") {
    return NextResponse.json({ error: "Only a teacher can publish a quiz" }, { status: 403 })
  }

  const course = await assertCourseAccess(principal, courseId)
  if (!course) return NextResponse.json({ error: "Course not found" }, { status: 404 })

  const body = await req.json().catch(() => ({}))
  const quizId = typeof body?.quizId === "string" ? body.quizId : ""
  const isPublished = body?.isPublished

  if (!quizId) return NextResponse.json({ error: "quizId is required" }, { status: 400 })
  if (typeof isPublished !== "boolean") {
    return NextResponse.json({ error: "isPublished must be a boolean" }, { status: 400 })
  }

  const supabase = await clientForPrincipal(principal)
  const { data, error } = await supabase
    .from("quizzes")
    .update({ is_published: isPublished })
    .eq("id", quizId)
    .eq("course_id", course.id)
    // Only a course-wide quiz can be released; a student's practice quiz is
    // private and must never be published to the class.
    .is("student_id", null)
    .select(QUIZ_COLUMNS)
    .maybeSingle()

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!data) {
    return NextResponse.json(
      { error: "Quiz not found, or it is a student's private practice quiz" },
      { status: 404 },
    )
  }

  return NextResponse.json({ quiz: data })
}

/** DELETE — remove a quiz. Teacher only, scoped to the course. */
export async function DELETE(req: Request, { params }: RouteContext) {
  const { courseId } = await params
  const principal = await resolvePrincipal()
  if (!principal) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

  if (principal.role !== "teacher" && principal.role !== "admin") {
    return NextResponse.json({ error: "Only a teacher can delete a quiz" }, { status: 403 })
  }

  const course = await assertCourseAccess(principal, courseId)
  if (!course) return NextResponse.json({ error: "Course not found" }, { status: 404 })

  const url = new URL(req.url)
  const quizId = url.searchParams.get("quizId") || ""
  if (!quizId) return NextResponse.json({ error: "quizId is required" }, { status: 400 })

  const supabase = await clientForPrincipal(principal)
  const { error } = await supabase
    .from("quizzes")
    .delete()
    .eq("id", quizId)
    .eq("course_id", course.id)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  return NextResponse.json({ success: true })
}
